OCF={2006:-104.0,2007:202.2,2008:148.9,2009:68.5,2010:-37.3,2011:-34.0,2012:-47.0,2013:-74.0,2014:-132.7,2015:-82.2,
     2016:34.2,2017:-52.5,2018:-2.6,2019:65.6,2020:168.3,2021:-16.8,2022:184.1,2023:552.1,2024:179.7,2025:137.3}
