JV={2006:17.0,2007:10.0,2008:5.2,2009:5.0,2010:1.2,2011:0.8,2012:1.8,2013:29.5,2014:20.4,2015:18.2,2016:21.7,2017:12.1,2018:31.9,2019:30.2,2020:28.5,2021:51.6,2022:20.1,2023:23.6,2024:54.1,2025:59.2}
