REV={2006:1274.1,2007:1016.5,2008:607.7,2009:569.9,2010:616.4,2011:566.4,2012:761.9,2013:1036.8,2014:1215.2,2015:1418.4,2016:1691.3,2017:1962.0,2018:2286.3,2019:2500.3,2020:3046.1,2021:3745.9,2022:4131.4,2023:4033.5,2024:4504.7,2025:4417.8}
PTI={2006:45.3,2007:-150.9,2008:-215.1,2009:-93.0,2010:-27.4,2011:-33.9,2012:12.7,2013:41.3,2014:69.7,2015:87.0,2016:91.8,2017:120.3,2018:141.3,2019:166.0,2020:310.1,2021:509.1,2022:635.2,2023:607.3,2024:733.6,2025:526.6}
TAXPAID={2021:109.9,2022:155.1,2023:150.7,2024:159.6,2025:131.4}
g=lambda d,y:d.get(y,0.0)
def oc(y,wh=False):
    v=OCF[y]-SBC[y]-PPE[y]+g(PPEsale,y)-JV[y]+g(JVret,y)-g(ACQ,y)+g(MSR,y)-g(PREF,y)
    return v+(g(WH,y) if wh else 0)
print(f"{'yr':>5}{'OCF':>8}{'OC':>8}{'OC+wh':>8}{'NI':>8}{'PTI':>8}{'REV':>8}")
for y in Y: print(f"{y:>5}{OCF[y]:8.1f}{oc(y):8.1f}{oc(y,True):8.1f}{NI[y]:8.1f}{PTI[y]:8.1f}{REV[y]:8.1f}")
s5=[oc(y) for y in range(2021,2026)]; s5w=[oc(y,True) for y in range(2021,2026)]
print("5yr avg OC strict %.1f  warehouse-adj %.1f"%(sum(s5)/5,sum(s5w)/5))
print("10yr avg OC 2016-25 strict %.1f adj %.1f"%(sum(oc(y) for y in range(2016,2026))/10,sum(oc(y,True) for y in range(2016,2026))/10))
t20=sum(oc(y) for y in Y); t20w=sum(oc(y,True) for y in Y)
print("20yr total OC strict %.1f adj %.1f; NI %.1f; REV %.1f; PTI %.1f"%(t20,t20w,sum(NI.values()),sum(REV.values()),sum(PTI.values())))
print("OC/REV 20y strict %.3f%% adj %.3f%%; PTI/REV %.3f%%; NI/REV %.3f%%"%(t20/sum(REV.values())*100,t20w/sum(REV.values())*100,sum(PTI.values())/sum(REV.values())*100,sum(NI.values())/sum(REV.values())*100))
print("5yr avg cash taxes %.1f"%(sum(TAXPAID.values())/5))
